INSERT INTO DimSecurity (SK_SecurityID, Symbol, Issue, Status, Name, ExchangeID, SK_CompanyID, SharesOutstanding, FirstTrade, FirstTradeOnExchange, Dividend, IsCurrent, BatchID, EffectiveDate, EndDate) WITH SecurityFinal AS (SELECT F.Symbol AS Symbol, F.IssueType AS Issue, ST.ST_NAME AS Status, F.Name AS Name, F.ExID AS ExchangeID, DimCo.SK_CompanyID AS SK_CompanyID, TRY_CAST(F.ShOut AS INT) AS SharesOutstanding, CAST(TRY_STRPTIME(F.FirstTradeDate, '%Y%m%d') AS DATE) AS FirstTrade, CAST(TRY_STRPTIME(F.FirstTradeExchg, '%Y%m%d') AS DATE) AS FirstTradeOnExchange, TRY_CAST(F.Dividend AS DECIMAL(18, 3)) AS Dividend, STRPTIME(F.PTS, '%Y%m%d-%H%M%S') AS EffectiveDate FROM Source.FinwireSEC AS F INNER JOIN DimCompany AS DimCo ON (CASE WHEN NOT TRY_CAST(F.CoNameOrCIK AS BIGINT) IS NULL THEN CAST(DimCo.CompanyID AS TEXT) ELSE DimCo.Name END) = F.CoNameOrCIK INNER JOIN StatusType AS ST ON F.Status = ST.ST_ID WHERE F.RecType = 'SEC' AND STRPTIME(F.PTS, '%Y%m%d-%H%M%S') >= DimCo.EffectiveDate AND STRPTIME(F.PTS, '%Y%m%d-%H%M%S') < DimCo.EndDate) SELECT ROW_NUMBER() OVER (ORDER BY Symbol, EffectiveDate) AS SK_SecurityID, Symbol, Issue, Status, Name, ExchangeID, SK_CompanyID, SharesOutstanding, FirstTrade, FirstTradeOnExchange, Dividend, CASE WHEN LEAD(EffectiveDate) OVER (PARTITION BY Symbol ORDER BY EffectiveDate ASC) IS NULL THEN TRUE ELSE FALSE END AS IsCurrent, 1 AS BatchID, EffectiveDate, COALESCE(LEAD(EffectiveDate) OVER (PARTITION BY Symbol ORDER BY EffectiveDate ASC), CAST('9999-12-31 00:00:00' AS TIMESTAMP)) AS EndDate FROM SecurityFinal ORDER BY Symbol, EffectiveDate;
